#include <datamunge/optim/interior_point.hpp>
#include <cmath>
#include <stdexcept>
namespace datamunge::optim { InteriorPoint::InteriorPoint(InteriorPointOptions o):options_(o){} double InteriorPoint::optimize(InequalityConstrainedFunction& f,std::vector<double>& x)const{double mu=options_.initial_barrier;for(std::size_t o=0;o<options_.max_outer_iterations;++o){for(std::size_t it=0;it<options_.inner_iterations;++it){auto c=f.inequalities(x);auto j=f.inequality_jacobian(x);auto g=f.gradient(x);for(std::size_t k=0;k<c.size();++k){if(c[k]>=0)throw std::invalid_argument("InteriorPoint: starting point must be strictly feasible");for(std::size_t p=0;p<x.size();++p)g[p]-=mu*j[k][p]/c[k];}double step=options_.step_size;for(;;){std::vector<double> y=x;for(std::size_t p=0;p<x.size();++p)y[p]-=step*g[p];auto trial=f.inequalities(y);bool feasible=true;for(double q:trial)if(q>=0)feasible=false;if(feasible){x=std::move(y);break;}step*=.5;if(step<1e-15)throw std::runtime_error("InteriorPoint: unable to find feasible step");}}mu*=options_.barrier_decay;}return f.evaluate(x);}}
